script:
let random = Math.floor(Math.random() * 10000);

bh.local.applicationId = "LN2026" + random;

console.log("Generated Application ID:", bh.local.applicationId);

let data = bh.input.body;

let errors = [];


// Default status
if (!data.status) {

    data.status = "DRAFT";
}


let isDraft =
    data.status === "DRAFT";

let isSubmitted =
    data.status === "SUBMITTED";


// --------------------
// DRAFT VALIDATIONS
// --------------------

if (isDraft) {

    if (
        !data.applicant_name
    ) {

        errors.push(
            "Applicant name required"
        );
    }

    if (
        data.email &&
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/
            .test(data.email)
    ) {

        errors.push(
            "Invalid email format"
        );
    }

    if (
        data.mobile &&
        !/^\d{10}$/
            .test(data.mobile)
    ) {

        errors.push(
            "Mobile must be 10 digits"
        );
    }
}


// --------------------
// SUBMITTED VALIDATIONS
// --------------------

if (isSubmitted) {

    let requiredFields = [

        "applicant_name",

        "dob",

        "gender",

        "mobile",

        "email",

        "address",

        "employment_type",

        "monthly_income",

        "loan_type",

        "loan_amount",

        "loan_tenure",

        "credit_score",

        "purpose_of_loan"
    ];


    requiredFields.forEach(field => {

        if (
            !data[field]
        ) {

            errors.push(
                `${field} is required`
            );
        }
    });


    // Email validation
    if (
        data.email &&
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/
            .test(data.email)
    ) {

        errors.push(
            "Invalid email format"
        );
    }


    // Mobile validation
    if (
        data.mobile &&
        !/^\d{10}$/
            .test(data.mobile)
    ) {

        errors.push(
            "Mobile must be 10 digits"
        );
    }


    // Age validation
    if (data.dob) {

        let dob =
            new Date(data.dob);

        let age =
            new Date()
            .getFullYear()
            - dob.getFullYear();

        if (
            age < 21 ||
            age > 60
        ) {

            errors.push(
                "Age must be between 21 and 60"
            );
        }
    }


    // Loan amount
    if (
        data.loan_amount <
            50000 ||

        data.loan_amount >
            5000000
    ) {

        errors.push(
            "Loan amount must be between 50,000 and 50,00,000"
        );
    }


    // Credit score
    if (
        data.credit_score <
            300 ||

        data.credit_score >
            900
    ) {

        errors.push(
            "Credit score must be between 300 and 900"
        );
    }


    // Income
    if (
        data.monthly_income <= 0
    ) {

        errors.push(
            "Monthly income must be positive"
        );
    }
}


if (errors.length > 0) {

    bh.input.error = {

        statusCode: 400,

        message:
            errors.join(", ")
    };

    throw new Error(
        errors.join(", ")
    );
}

bh.local.loanData = data;

let loanAmount = bh.local.loanData.loan_amount;

let tenureMonths = bh.local.loanData.loan_tenure;

let annualInterestRate = 8.5;

let monthlyIncome = bh.local.loanData.monthly_income;

let creditScore = bh.local.loanData.credit_score;


// Monthly Interest Rate
let monthlyRate = annualInterestRate / 12 / 100;


// EMI Formula
let emi =
    (loanAmount *
        monthlyRate *
        Math.pow(1 + monthlyRate, tenureMonths)) /
    (Math.pow(1 + monthlyRate, tenureMonths) - 1);


// Debt To Income Ratio
let dti = emi / monthlyIncome;


// Risk Logic
let riskCategory = "HIGH";

if (creditScore >= 750 && dti < 0.4) {
    riskCategory = "LOW";
}
else if (creditScore >= 650 && dti < 0.6) {
    riskCategory = "MEDIUM";
}


// Store Data
bh.local.calculatedMetrics = {
    interest_rate: annualInterestRate,

    emi: Number(emi.toFixed(2)),

    debt_to_income_ratio:
        Number(dti.toFixed(2)),

    risk_category: riskCategory
};

console.log(
    "Calculated Metrics:",
    bh.local.calculatedMetrics
);

let risk =
    bh.local.calculatedMetrics.risk_category;

let decision = "";
let status = "";


if (risk === "LOW") {

    decision = "AUTO_APPROVE";

    status = "APPROVED";

}
else if (risk === "MEDIUM") {

    decision = "LOAN_OFFICER_REVIEW";

    status = "UNDER_REVIEW";

}
else {

    decision = "CREDIT_MANAGER_REVIEW";

    status = "UNDER_REVIEW";
}


bh.local.loanDecision = decision;

bh.local.loanStatus = status;

console.log("Decision:", decision);

console.log("Status:", status);

let assignedRole = "";

if (bh.local.loanDecision === "AUTO_APPROVE") {

    assignedRole = "CREDIT_MANAGER";

}
else if (
    bh.local.loanDecision ===
    "LOAN_OFFICER_REVIEW"
) {

    assignedRole = "LOAN_OFFICER";

}
else {

    assignedRole = "CREDIT_MANAGER";

}

bh.local.assignedRole = assignedRole;

console.log(
    "Assigned Role:",
    assignedRole
);

bh.output = {

    success: true,

    message: "Loan application created successfully",

    data: bh.local.updateFinalResult || bh.local.insertResult
};

bh.output = {

    success: true,

    message:
        "Loan application saved as draft successfully",

    data: {

        application_id:
            bh.local.loanData.application_id,

        applicant_name:
            bh.local.loanData.applicant_name,

        status:
            "DRAFT"
    }
};

bh.output = {

    success: false,

    statusCode:
        bh.input.error?.statusCode || 500,

    message:
        bh.input.error?.message
        || "Something went wrong"
};
